// 2-Dars: Terminal va CLI buyruqlari. package.json fayli va npm skriptlarini sozlash
{
  "name": "backend-app",
  "scripts": {
    "start": "node index.js"
  }
}

// 3-Dars: CommonJS (require/module.exports) va ES Modules (import/export) sintaksisi
const math = require('./math');
module.exports = { math };

// 5-Dars: File System (fs) moduli: Sinxron va Asinxron fayl operatsiyalari
const fs = require('fs').promises;
await fs.writeFile('file.txt', 'Hello World');

// 6-Dars: Path va OS modullari orqali operatsion sistema bilan ishlash
const path = require('path');
const filePath = path.join(__dirname, 'data.json');

// 7-Dars: Asinxron dasturlash: Callbacks, Promises va Async/Await mantiqlari
async function fetchData() {
  return new Promise((resolve) => resolve('Data'));
}

// 8-Dars: Events (EventEmitter) moduli va voqealarga asoslangan arxitektura
const EventEmitter = require('events');
const emitter = new EventEmitter();
emitter.on('userCreated', (user) => {});

// 9-Dars: Buffer va Streams: Katta ma'lumotlar oqimi (ReadStream, WriteStream)
const fs = require('fs');
const readStream = fs.createReadStream('large.txt');

// 10-Dars: HTTP moduli: Birinchi nativ Node.js web serverini yaratish
const http = require('http');
const server = http.createServer((req, res) => {
  res.end('Server Active');
});
server.listen(3000);

// 11-Dars: URL parsing, HTTP Metodlar (GET, POST) va Query parametrlarini olish
const url = require('url');
const myUrl = new URL(req.url, 'http://localhost:3000');

// 12-Dars: HTTP Status kodlar va JSON formatida javob qaytarish (res.writeHead, res.end)
res.writeHead(200, { 'Content-Type': 'application/json' });
res.end(JSON.stringify({ status: 'ok' }));

// 13-Dars: Express.js frameworkini o'rnatish va birinchi Express serverini ishga tushirish
const express = require('express');
const app = express();
app.listen(5000, () => console.log('Server 5000-portda ishlamoqda'));

// 14-Dars: Express Routing: GET, POST, PUT, PATCH va DELETE marshrutlarini yaratish
app.get('/users', (req, res) => res.json([]));
app.post('/users', (req, res) => res.status(201).json(req.body));

// 15-Dars: Middleware (Oraliq dastur) tushunchasi va custom middleware yozish
const logger = (req, res, next) => {
  console.log(`${req.method} ${req.url}`);
  next();
};
app.use(logger);

// 16-Dars: Request Body parsing: express.json() va express.urlencoded()
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// 17-Dars: Route Parameters (req.params) va Query Strings (req.query) bilan ishlash
app.get('/products/:id', (req, res) => {
  const { id } = req.params;
  const { sort } = req.query;
});

// 18-Dars: Express Router orqali marshrutlarni modullarga ajratish va guruhlash
const router = require('express').Router();
router.get('/', (req, res) => {});
module.exports = router;

// 19-Dars: Global Error Handling Middleware: Server xatolarini markazlashgan boshqaruv
app.use((err, req, res, next) => {
  res.status(500).json({ error: err.message });
});

// 20-Dars: Static fayllarni uzatish: express.static middleware sozlamalari
const path = require('path');
app.use('/public', express.static(path.join(__dirname, 'public')));

// 21-Dars: CORS (Cross-Origin Resource Sharing) va xavfsiz domen so'rovlari
const cors = require('cors');
app.use(cors({ origin: 'http://localhost:5173' }));

// 22-Dars: Multer kutubxonasi orqali fayl va rasmlarni serverga yuklash (File Upload)
const multer = require('multer');
const upload = multer({ dest: 'uploads/' });
app.post('/upload', upload.single('file'), (req, res) => {});

// 23-Dars: express-validator orqali kiruvchi so'rov ma'lumotlarini tekshirish (Validation)
const { body, validationResult } = require('express-validator');
app.post('/user', body('email').isEmail(), (req, res) => {});

// 25-Dars: Ma'lumotlar bazasi tushunchasi. MongoDB NoSQL bazasi va Compass dasturi
// MongoDB NoSQL hujjati namunasi
const userDoc = { _id: '123', name: 'Ali', email: 'ali@mail.com' };

// 26-Dars: Mongoose ODM ni o'rnatish va MongoDB bazasiga ulanish (mongoose.connect)
const mongoose = require('mongoose');
await mongoose.connect(process.env.MONGO_URI);

// 27-Dars: Mongoose Schema va Model tushunchasi: Ma'lumotlar strukturasini loyihalash
const userSchema = new mongoose.Schema({ name: String, age: Number });
const User = mongoose.model('User', userSchema);

// 32-Dars: Mongoose Schema Validation: Majburiy maydonlar, unikal qiymatlar va turlar
const emailSchema = new mongoose.Schema({
  email: { type: String, required: true, unique: true }
});

// 34-Dars: Mongoose Aggregation Pipeline: $match, $group, $sort va $project operatsiyalari
const stats = await Order.aggregate([
  { $match: { status: 'COMPLETED' } },
  { $group: { _id: '$userId', total: { $sum: '$amount' } } }
]);

// 35-Dars: Mongoose Middleware Hooks (Pre va Post save/remove ilgaklari)
userSchema.pre('save', async function(next) {
  // Pre save logic
  next();
});

// 37-Dars: Parollarni xavfsiz saqlash: bcryptjs orqali parolni xeshlashtirish va tuzlash
const bcrypt = require('bcryptjs');
const hashedPassword = await bcrypt.hash('password123', 10);

// 38-Dars: JWT (JSON Web Token) nima va u qanday ishlaydi? Access Token yaratish
const jwt = require('jsonwebtoken');
const token = jwt.sign({ id: user._id }, process.env.JWT_SECRET, { expiresIn: '1d' });

// 39-Dars: Authentication Middleware: JWT Tokenni tekshirish va foydalanuvchini aniqlash
const token = req.headers.authorization?.split(' ')[1];
const decoded = jwt.verify(token, process.env.JWT_SECRET);

// 40-Dars: Role-Based Access Control (RBAC): Admin va Foydalanuvchi huquqlarini ajratish
const checkRole = (...roles) => (req, res, next) => {
  if (!roles.includes(req.user.role)) return res.status(403).json({ message: 'Denied' });
  next();
};

// 42-Dars: Helmet.js va HTTP Headerlarini xavfsizlantirish
const helmet = require('helmet');
app.use(helmet());

// 43-Dars: Rate Limiting: express-rate-limit orqali Brute-Force va DDoS himoyasi
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({ windowMs: 15 * 60 * 1000, max: 100 });
app.use(limiter);

// 44-Dars: NoSQL Injection va XSS xurujlaridan express-mongo-sanitize va xss orqali himoya
const mongoSanitize = require('express-mongo-sanitize');
app.use(mongoSanitize());

// 48-Dars: OAuth 2.0 va Google / Telegram orqali avtorizatsiya integratsiyasi
const passport = require('passport');
app.use(passport.initialize());

// 49-Dars: TypeScript asoslari Backend dasturchilar uchun: Types, Interfaces va Generics
interface User {
  id: string;
  name: string;
  role: 'ADMIN' | 'STUDENT';
}

// 50-Dars: NestJS Framework kirish: Arxitektura va Nest CLI yordamida loyiha yaratish
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  await app.listen(3000);
}

// 51-Dars: NestJS Controllers: Marshrutizatsiya va HTTP so'rov dekoratorlari (@Get, @Post)
@Controller('users')
export class UsersController {
  @Get()
  findAll() { return []; }
}

// 52-Dars: NestJS Providers va Services: Biznes mantiqni modullashtirish
@Injectable()
export class UsersService {
  getUsers() { return ['User 1']; }
}

// 54-Dars: DTO (Data Transfer Object) va class-validator / class-transformer
import { IsEmail, IsNotEmpty } from 'class-validator';
export class CreateUserDto {
  @IsEmail()
  email: string;
}

// 55-Dars: NestJS Modules: Modullarga bo'lingan (Feature Modules) arxitektura
@Module({
  controllers: [UsersController],
  providers: [UsersService],
})
export class UsersModule {}

// 56-Dars: NestJS Guards: JwtAuthGuard va RolesGuard yaratish
@Injectable()
export class JwtAuthGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean { return true; }
}

// 57-Dars: NestJS Interceptors va Custom Pipes: Ma'lumotlarni o'zgartirish va responselar
@Injectable()
export class TransformInterceptor implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler) { return next.handle(); }
}

// 58-Dars: NestJS Mongoose integratsiyasi (@InjectModel va Schemas)
import { InjectModel } from '@nestjs/mongoose';
constructor(@InjectModel(User.name) private userModel: Model<UserDocument>) {}

// 59-Dars: Swagger (OpenAPI) hujjatlashtirish va @ApiTags, @ApiOperation sozlash
@ApiTags('Auth')
@ApiOperation({ summary: 'Login User' })
export class AuthController {}

// 60-Dars: Exception Filters: NestJS xatoliklarni global ushlash va qayta ishlash
@Catch()
export class AllExceptionsFilter implements ExceptionFilter {
  catch(exception: any, host: ArgumentsHost) {}
}

// 61-Dars: Relatsion ma'lumotlar bazasi tushunchasi va PostgreSQL o'rnatish
CREATE TABLE users (
  id SERIAL PRIMARY KEY,
  name VARCHAR(100) NOT NULL
);

// 63-Dars: TypeORM / Prisma ORM orqali PostgreSQL bilan ishlash
import { Entity, PrimaryGeneratedColumn, Column } from 'typeorm';
@Entity()
export class User {
  @PrimaryGeneratedColumn()
  id: number;
}

// 64-Dars: Relatsiyalar (Relations): One-to-One, One-to-Many va Many-to-Many
@ManyToOne(() => Group, (group) => group.students)
group: Group;

// 65-Dars: Redis Caching: Tez-tez murojaat qilinadigan ma'lumotlarni keshga olish
const Redis = require('ioredis');
const redis = new Redis();
await redis.set('user:1', JSON.stringify({ name: 'Ali' }), 'EX', 3600);

// 66-Dars: WebSockets va Socket.io: Real-time tezkor xabar almashish serveri
const io = require('socket.io')(server);
io.on('connection', (socket) => {
  socket.on('message', (data) => io.emit('message', data));
});

// 67-Dars: Task Scheduling: BullMQ va Cron Jobs orqali orqa fondagi vazifalar
import { Cron, CronExpression } from '@nestjs/schedule';
@Cron(CronExpression.EVERY_DAY_AT_MIDNIGHT)
handleCron() {}

// 68-Dars: Microservices arxitekturasi asoslari va RabbitMQ bilan xabarlar almashish
// Microservice Message Pattern
@MessagePattern({ cmd: 'get_user' })
getUser(data: any) { return data; }

// 71-Dars: Jest va Supertest yordamida Unit va Integration testlar yozish
const request = require('supertest');
describe('GET /api/users', () => {
  it('should return 200 OK', async () => {
    await request(app).get('/api/users').expect(200);
  });
});
